ALTER TABLE `organizations` ADD COLUMN `logo_url` VARCHAR(500) NULL AFTER `name`;
ALTER TABLE `teams` ADD COLUMN `lead_membership_id` CHAR(36) CHARACTER SET ascii NULL AFTER `name`, ADD COLUMN `default_workflow_key` VARCHAR(80) CHARACTER SET ascii NULL AFTER `lead_membership_id`, ADD KEY `idx_teams_lead` (`organization_id`,`lead_membership_id`), ADD CONSTRAINT `fk_teams_lead_membership` FOREIGN KEY (`lead_membership_id`) REFERENCES `memberships` (`id`) ON DELETE RESTRICT;
CREATE TABLE `team_memberships` (`team_id` CHAR(36) CHARACTER SET ascii NOT NULL,`membership_id` CHAR(36) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`team_id`,`membership_id`),KEY `idx_team_membership_member` (`membership_id`,`team_id`),CONSTRAINT `fk_team_membership_team` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_team_membership_membership` FOREIGN KEY (`membership_id`) REFERENCES `memberships` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_team_membership_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `organization_invitations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`email` VARCHAR(254) NOT NULL,`email_normalized` VARCHAR(254) NOT NULL,`role_code` VARCHAR(64) CHARACTER SET ascii NOT NULL,`status` ENUM('pending_delivery','pending_acceptance','accepted','expired','revoked') NOT NULL,`expires_at` DATETIME(3) NOT NULL,`invited_by` CHAR(36) CHARACTER SET ascii NOT NULL,`accepted_membership_id` CHAR(36) CHARACTER SET ascii NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),KEY `idx_org_invitation_status` (`organization_id`,`status`,`expires_at`),KEY `idx_org_invitation_email` (`organization_id`,`email_normalized`,`status`),CONSTRAINT `fk_org_invitation_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_invitation_role` FOREIGN KEY (`role_code`) REFERENCES `roles` (`code`) ON DELETE RESTRICT,CONSTRAINT `fk_org_invitation_inviter` FOREIGN KEY (`invited_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_invitation_membership` FOREIGN KEY (`accepted_membership_id`) REFERENCES `memberships` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `organization_api_tokens` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`name` VARCHAR(120) NOT NULL,`token_prefix` VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`token_hash` CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`scopes_json` JSON NOT NULL,`status` ENUM('active','revoked','rotated','expired') NOT NULL,`expires_at` DATETIME(3) NOT NULL,`last_used_at` DATETIME(3) NULL,`rotated_from_id` CHAR(36) CHARACTER SET ascii NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revoked_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_org_token_hash` (`token_hash`),KEY `idx_org_token_status` (`organization_id`,`status`,`expires_at`),CONSTRAINT `fk_org_token_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_token_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_token_revoker` FOREIGN KEY (`revoked_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_token_rotated_from` FOREIGN KEY (`rotated_from_id`) REFERENCES `organization_api_tokens` (`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `organization_admin_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(180) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_org_admin_operation` (`organization_id`,`actor_id`,`route_key`,`idempotency_key`),KEY `idx_org_admin_operation_resource` (`organization_id`,`resource_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
